                    stream.Write(gtmpMessage, 0, gtmpMessage.Length);

                    response = new byte[256];
                    bytesRead = stream.Read(response, 0, response.Length);
                    string temperature = Encoding.ASCII.GetString(response, 0, bytesRead);
                    Console.WriteLine("Temperature: " + temperature);
                }

                // Send the logout message to close the connection gracefully.
                byte[] logoutMessage = Encoding.ASCII.GetBytes("LOGOUT");
                stream.Write(logoutMessage, 0, logoutMessage.Length);

                // Close the client and the stream.
                client.Close();
            }
            catch (Exception e)
            {
                Console.WriteLine("Error: " + e);
            }

            Console.ReadLine();
        }
    }
}
