    let name: String
    let type: Type
}

enum Type {
    case float
    case int
    case bool
    case sampler
    // Add more types as needed
}

enum Statement {
    case declaration(VariableDeclaration)
    case assignment(Expression, Expression)
    case functionCall(String, [Expression])
    // Add more statement types as needed

    var description: String {
        switch self {
        case .declaration(let declaration):
            return declaration.description
        case .assignment(let lhs, let rhs):
            return "\(lhs) = \(rhs)"
        case .functionCall(let function, let arguments):
            return "\(function)(\(arguments.map { $0.description }.joined(separator: ", ")))"
        }
    }
}

struct VariableDeclaration {
    let name: String
    let type: Type
    let initialValue: Expression?
}

enum Expression {
    case identifier(String)
    case number(Double)
    case binaryOperation(BinaryOperator, Expression, Expression)
    // Add more expression types as needed

