        switch self {
        case .identifier(let name):
            return name
        case .number(let number):
            return String(number)
        case .binaryOperation(let operator, let lhs, let rhs):
            return "\(lhs) \(operator) \(rhs)"
        }
    }
}

enum BinaryOperator {
    case add
    case subtract
    case multiply
    case divide
    // Add more binary operators as needed
